// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2016, "8-9", [{"author":"А. Сомин","question":"<em>В ночь на понедельник на улице было ‒25 градусов, но к утру мороз спал.</em> Здесь последнее слово — это форма глагола … .","choices":["<em>спасть</em>","<em>спасти</em>","<em>спасать</em>","<em>спать</em>","<em>спалить</em>."],"key":"А","review":["Мороз к утру","Сравни значения «мороз спал» и «снег спал с веток». В обоих случаях речь об уменьшении или исчезновении чего-то.","Мороз ослаб, то есть спал. «Спал» в этой фразе — прошедшее время глагола «спасть»."]},{"author":"Б. и М. Иомдины","question":"Как нельзя сказать?","choices":["<em>К ночи улицы быстро пустеют.</em>","<em>Школа на каникулах пустует.</em>","<em>Банка варенья постепенно пустует.</em>","<em>Тарелка с фруктами стремительно пустеет.</em>","<em>Зимой посёлок наполовину пустует.</em>"],"key":"В","review":["Состояние и изменение","«Пустеть» означает становиться пустым, а «пустовать» — быть пустым в течение некоторого времени.","В банке варенья постепенно становится меньше, поэтому она пустеет. «Банка постепенно пустует» не передаёт изменения, которое описывает «постепенно»."]},{"author":"Б. Иомдин","question":"Какое слово употребляется не так, как остальные?","choices":["<em>величество</em>","<em>высочество</em>","<em>господство</em>","<em>превосходительство</em>","<em>сиятельство</em>."],"key":"В","review":["Формула обращения","Проверь, с какими из этих слов можно обратиться к человеку, прибавив «Ваше».","Есть обращения «Ваше Величество», «Ваше Высочество», «Ваше Превосходительство» и «Ваше Сиятельство». Слово «господство» обозначает власть или преобладание."]},{"author":"С. Сай","question":"Многие русские предлоги имеют по два варианта, например: <em>в</em> и <em>во</em>. А у какого предлога есть три варианта?","choices":["<em>из</em>","<em>к</em>","<em>на</em>","<em>о</em>","<em>от</em>."],"key":"Г","review":["Варианты предлога","Подставь предлоги к словам разной звуковой формы. Для искомого предлога нужен ещё вариант перед «мне».","Сравни «о книге», «об экскурсии» и «обо мне». У этого предлога три формы — «о», «об», «обо»."]},{"author":"О. Подлесская","question":"В какой паре глаголы не являются антонимами?","choices":["<em>удлинять — укорачивать</em>","<em>расшириться — сузиться</em>","<em>повышать — понижать</em>","<em>удаляться — приближаться</em>","<em>утвердить — смягчить</em>."],"key":"Д","review":["Действия с обратным смыслом","Определи, описывает ли второй глагол обратное изменение того же свойства, например длины или расстояния.","«Утвердить» — принять или подтвердить, а «смягчить» — сделать мягче. Эти действия не противоположны. Остальные четыре пары описывают обратные изменения."]},{"author":"И. Иткин","question":"Словосочетание <em>удачный выбор</em> нельзя заменить оборотом с родительным падежом: выражение <em>выбор удачи</em>, если и существует, имеет совершенно другой смысл. Для какого из приведённых словосочетаний такая замена возможна?","choices":["<em>дружный смех</em>","<em>честное слово</em>","<em>вечный город</em>","<em>трудная задача</em>","<em>правильный ответ</em>."],"key":"Б","review":["Замена родительным падежом","Ищи устойчивую фразу, которую можно выразить через существительное со значением качества, не меняя её смысла.","«Честное слово» и «слово чести» называют обещание, за которое человек ручается своей честью. «Смех дружбы» или «задача трудности» не равнозначны исходным выражениям."]},{"author":"А. Сомин","question":"Польское выражение «za króla Ćwieczka» (дословно «<em>во времена короля Гво́здика</em>») на русский можно перевести фразой, в которой есть слово … .","choices":["<em>Кукуруза</em>","<em>Чечевица</em>","<em>Боб</em>","<em>Горох</em>","<em>Фасоль</em>."],"key":"Г","review":["Польский король","Выражение отсылает к сказочному правителю и означает «давным-давно». Вспомни русского царя из такой же поговорки.","По-русски говорят «при царе Горохе». В польской поговорке место вымышленного царя занимает король Гвоздик."]},{"author":"П. Аркадьев","question":"В каком случае на месте пропуска нельзя вставить букву <em>е</em>?","choices":["<em>посв…тить</em>","<em>просв…щённый</em>","<em>осв…тить</em>","<em>посв…щённый</em>","букву <em>е</em> можно вставить во всех случаях (А)–(Г)."],"key":"Г","review":["Гласная в пропуске","Ищи проверочные слова с ударной гласной. У одной пары существуют два слова с различным смыслом, поэтому нужна внимательная проверка.","Можно «посветить» и «осветить» фонарём, а человек бывает «просвещённым». В сочетании «посвящённый юбилею» пишется «я»."]},{"author":"П. Аркадьев и И. Иткин","question":"В какой паре слова по-разному образуют форму именительного падежа множественного числа?","choices":["<em>строитель — кораблестроитель</em>","<em>учитель — самоучитель</em>","<em>хранитель — предохранитель</em>","<em>свидетель — лжесвидетель</em>","во всех парах им. п. мн. ч. образуется одинаково."],"key":"Б","review":["Множественное число в парах","Поставь существительные в именительный падеж множественного числа и сравни окончания внутри каждой пары.","«Учитель» даёт «учителя́», а «самоучитель» — «самоучи́тели». В остальных парах окончания слова и его производного совпадают."]},{"author":"Е. Бикмаев","question":"Журналист использовал в репортаже выражение французского происхождения <em>тет-а-тет</em>. Редактор потребовал заменить заимствованное выражение русским. Подскажите, чем его лучше заменить.","choices":["<em>лицом к лицу</em>","<em>нога в ногу</em>","<em>плечом к плечу</em>","<em>с глазу на глаз</em>","<em>голова к голове</em>."],"key":"Г","review":["Замена французского оборота","«Тет-а-тет» описывает разговор двух людей без посторонних. Ищи русское выражение именно для разговора наедине.","Подходит «с глазу на глаз». «Лицом к лицу» может описывать встречу или столкновение и само по себе не указывает на отсутствие посторонних."]},{"author":"А. Пиперски","question":"Даны пять стихотворных фрагментов, в которых пропущены одинаковые слова. В каком из них эти слова стоят в необычном порядке?","choices":["<em>_________ повторив, что это лишь обряд, / Они для памяти причастие творят.</em> (В. Брюсов)","<em>Все пустыни _________ от века родны, / Но Аравия, Сирия, Гоби — Это лишь затиханье сахарской волны, / В сатанинской воспрянувшей злобе.</em> (Н. Гумилёв)","<em>Дворяне — все родня _________, / И приучили их века / Глядеть в лицо другому кругу / Всегда немного свысока.</em> (А. Блок)","<em>Я голос твой далекий слышу, / _________ нам нельзя помочь.</em> (А. Тарковский)","<em>И каждый стих с другим, как близкий брат, / хоть шепчет _________: чуть-чуть подвинься. / Но каждый так далек от райских врат, / так беден, густ, так чист, что в них — единство.</em> (И. Бродский)"],"key":"Д","review":["Два слова в стихах","Подставь «друг другу» в каждый пропуск и проверь, удобно ли фраза ложится в стихотворный ритм.","В четырёх фрагментах порядок «друг другу». В стихе Бродского стоит «хоть шепчет другу друг». «Другу» и «друг» идут в обратном порядке."]},{"author":"И. Погодаев","question":"<em>Треугольник — не округлить, немилость — не сломить, деньжат — ... .</em>","choices":["<em>не заработать</em>","<em>не потратить</em>","<em>не взять</em>","<em>ненайти</em>","<em>неждать</em>."],"key":"Д","review":["Перестановка букв","Сопоставь слова около тире. Проверь, встречаются ли одинаковые буквы в слове «треугольник» и в сочетании «не округлить».","Справа каждый раз переставлены буквы левой части. Из «деньжат» тем же способом получается «неждать». Сохраняем слитное написание, как в варианте."]},{"author":"О. Подлесская","question":"В каком отрывке слово <em>что</em> отличается по значению от остальных употреблений?","choices":["<em>Что слава? ― Яркая заплата / На ветхом рубище певца.</em> (А. Пушкин)","<em>Ну, что соседки? Что Татьяна? Что Ольга резвая твоя?</em> (А. Пушкин)","<em>— Ну, что море, что небо? какие краски там? — слышу я ваши вопросы.</em> (И. Гончаров)","<em>«Ну, что ваш внук?» ― / «Писал недавно».</em> (Н. Огарёв)","<em>— Что ж лошади? — спросила она вошедшего человека. — Давно готовы-с.</em> (Ф. Достоевский)"],"key":"А","review":["Значение вопросительного слова","В четырёх цитатах спрашивают о том, как обстоят дела у кого-то или с чем-то. Найди вопрос о самом значении понятия.","В «Что слава?» спрашивают «Что такое слава?». В остальных фрагментах «что» можно развернуть в «как поживает?» или «что с этим происходит?»."]},{"author":"Б. Иомдин","question":"<em>Битву, изображённую на древней моза_ке, вы_грали во_ны Та_ланда</em>. В скольких местах мы пропустили букву <em>й</em>?","choices":["ни в одном","в одном","в двух","в трёх","в четырёх."],"key":"А","review":["Четыре буквенных пропуска","Запиши слова по одному. Различай буквы «и» и «й» в словах с двумя соседними гласными.","Получаются «мозаике», «выиграли», «воины» и «Таиланда». В каждом пропуске нужна «и», поэтому букв «й» нет."]},{"author":"К. Шагал","question":"Настоящее имя французского карикатуриста <em>Эффеля</em> — ... .","choices":["<em>Франсуа Лежён</em>","<em>Шарль Филипон</em>","<em>Этьен Каржа</em>","<em>Жан Кабю</em>","<em>Бенжамен Рубо</em>."],"key":"А","review":["Имя карикатуриста","Произнеси «Эффель» как названия двух французских букв. Так можно узнать инициалы имени.","«Эффель» передаёт звучание «F. L.». С этими инициалами из списка совпадает только Франсуа Лежён."]},{"author":"Б. Иомдин","question":"Дано толкование из словаря иностранных слов: «Торжественное собрание в учебных заведениях (по поводу выпуска, вручения наград и т. п.)». Какое слово истолковано?","choices":["<em>акт</em>","<em>бал</em>","<em>бонус</em>","<em>диплом</em>","<em>митинг</em>."],"key":"А","review":["Словарное определение","Представь торжественное собрание в училище или гимназии. Среди вариантов ищи название собрания, а не развлечения или награды.","В таком значении «акт» — торжественное собрание учебного заведения, например по случаю выпуска."]},{"author":"Л. Фёдорова","question":"Какой бывает фраза?","choices":["цветной","цветовой","цветочной","цветастой","цветистой."],"key":"Д","review":["Фраза с украшениями","Нужен переносный смысл: у фразы может быть яркое звучание и множество выразительных оборотов.","О богатой украшениями фразе говорят «цветистая». Отсюда сочетание «цветистая фраза»."]},{"author":"А. Пиперски","question":"Сколько причастий среди слов <em>берущий</em>, <em>большущий</em>, <em>загребущий</em>, <em>пропащий</em>, <em>тощий</em>?","choices":["одно","два","три","четыре","пять."],"key":"А","review":["Глагольный признак","Для каждого слова попробуй назвать глагол и перефразировать его через «который что-то делает».","«Берущий» — «который берёт», действительное причастие. Остальные слова употребляются как прилагательные."]},{"author":"Е. Бикмаев","question":"Женя выписывал слова, связанные с кораблями. Где он ошибся?","choices":["<em>судостроение</em>","<em>судопроизводство</em>","<em>судовладелец</em>","<em>судоремонт</em>","<em>судоходство.</em>"],"key":"Б","review":["Значения слова «суд»","Проверь, с чем связано каждое слово — с кораблём или с рассмотрением дел в суде.","Судопроизводство — порядок рассмотрения дел судом. Судостроение, судовладелец, судоремонт и судоходство связаны с судами-кораблями."]},{"author":"Б. Иомдин и Ю. Халеева","question":"<em>Август среди участниц «Русского медвежонка» встретилось немного.</em> А сколько ещё названий месяцев можно подставить вместо первого слова, чтобы фраза оставалась грамматически правильной?","choices":["ни одного","одно","два","три","четыре."],"key":"В","review":["Имена в строке о конкурсе","После «немного» нужна форма родительного падежа множественного числа. «Август» — как раз такая форма женского имени «Августа».","Подходят ещё «Март» от «Марта» и «Май» от «Майя». В обоих случаях форма имени совпадает с названием месяца."]},{"author":"А. Пиперски","question":"Русское слово <em>тетрадь</em> происходит из греческого. Догадавшись, от какого корня оно образовано, определите, как это слово переводится на итальянский.","choices":["terzina","quaderno","quinta","sextino","settimana."],"key":"Б","review":["Тетрадь по-итальянски","Греческое «тетра-» указывает на четыре. Найди итальянское слово с частью, которая означает то же число.","«Quaderno» значит «тетрадь». В нём исторически сохранилась основа со значением «четыре», как и в русском слове греческого происхождения."]},{"author":"А. Пиперски","question":"Некоторые русские числительные примечательны тем, что в них при склонении изменяется не только конец слова, но и середина: например, <em>пятьдесят</em> — <em>пятидесяти</em>. А какое географическое название рекомендовалось склонять похожим образом ещё в середине XIX века?","choices":["<em>Волоколамск</em>","<em>Екатеринослав</em>","<em>Новгород</em>","<em>Симбирск</em>","<em>Тобольск</em>."],"key":"В","review":["Две изменяемые части","Поищи название, которое можно мысленно разобрать на старое прилагательное и существительное. В старом склонении могли изменяться оба.","«Новгород» исторически сложился из «новъ» и «городъ». В старых формах вроде «Нова города» изменялись и первая часть, и вторая."]},{"author":"А. Пиперски","question":"29 ноября 2015 года логотип поисковой системы Google для российских пользователей выглядел так (за исключением небольшой детали, которую мы от вас скрыли):\nА что за деталь мы скрыли?","choices":["пятиконечную звезду","треугольник и квадрат","две точки","пчелу","корни у дерева."],"key":"В","review":["Ноябрьский логотип","Назови предметы на картинке и сравни букву, которая встречается в их русских названиях.","Ёж, лёд, мёд и ёлка содержат «ё». Логотип посвятили этой букве, а художник задания скрыл две точки над «е»."],"figure":{"condition":{"src":"assets/medvezhonok/2016/8-9-23-doodle.webp","alt":"Слева направо: киноплёнка с буквой G, ёж, кубик льда, пчелиные соты с мёдом, украшенная ёлка и строчная буква е.","detailSrc":"assets/medvezhonok/2016/8-9-23-doodle-detail.webp","pixelWidth":2665,"pixelHeight":1258}}},{"author":"П. Аркадьев","question":"Сколько глаголов из данного списка: <em>возвещать</em>, <em>завещать</em>, <em>извещать</em>, <em>обещать</em>, <em>оповещать</em>, <em>предвещать</em> — относится только к несовершенному виду?","choices":["все","пять","четыре","три","два."],"key":"В","review":["Виды глаголов с «-вещать»","Попробуй употребить каждый глагол для завершённого действия, например «он уже обещал» в смысле «пообещал».","«Завещать» и «обещать» могут употребляться в обоих видах. «Возвещать», «извещать», «оповещать» и «предвещать» — несовершенного вида."]},{"author":"Е. Бикмаев","question":"В древнерусском языке было слово <em>тьло</em>, и следы этого сохранились в современном русском языке. Определите значение этого слова.","choices":["‘вершина’","‘основание’","‘ребро’","‘грань’","‘плоскость’."],"key":"Б","review":["Старое слово «тьло»","Вспомни оборот «сгореть дотла». Что от строения остаётся, если всё над этим уровнем сгорело?","«Дотла» буквально значит «до основания». Это старое значение слова «тьло» сохранилось в наречии."]},{"author":"А. Пиперски","question":"В одной работе по словообразованию есть список, в котором упомянуты, в частности, такие глаголы: <em>болтать</em>, <em>ворчать</em>, <em>врать</em>, <em>говорить</em>, <em>опекать</em>, <em>хвастать</em>. Какой ещё глагол есть в этом списке?","choices":["<em>бредить</em>","<em>косить</em>","<em>молчать</em>","<em>спасать</em>","<em>убеждать</em>."],"key":"В","review":["Глагол и название человека","От глаголов из списка можно образовать названия людей по действию или привычке. Сравни «ворчать — ворчун» и «врать — врун».","Получаются «болтун», «ворчун», «врун», «говорун», «опекун», «хвастун». По той же модели от «молчать» образуется «молчун»."]},{"author":"А. Сомин","question":"Произношение названия какой из этих станций московского метро изменилось к концу 90-х годов из-за одной особенности русской орфографии?","choices":["<em>Красносельская</em>","<em>Пионерская</em>","<em>Алексеевская</em>","<em>Планерная</em>","<em>Новокузнецкая</em>."],"key":"Г","review":["Название станции метро","Вспомни, какой звук часто скрывается за буквой «е» в надписях и на схемах, если над ней не поставили точки.","Станция первоначально называлась «Планёрная». При обычной записи без точек её стали читать «Пла́нерная», и новое произношение закрепилось."]},{"author":"М. Коношенко","question":"Перед вами первая строфа стихотворения Владислава Ходасевича «Вечер» и ещё пять строк того же автора:\n<em>Под ногами скользь и хруст.\nВетер дунул, снег пошёл.\nБоже мой, какая грусть!\nГосподи, какая боль!</em>\n1) <em>Верить, коченеть и петь</em>;\n2) <em>И к чему такая ширь</em>;\n3) <em>А когда настанет срок</em>;\n4) <em>Не смутят моих детей</em>;\n5) <em>Да и Ты немилосерд</em>.\nКакие из приведённых выше строк взяты из другого стихотворения?","choices":["1 и 3","2 и 4","3 и 4","3 и 5","4 и 5."],"key":"В","review":["Строки Ходасевича","Стихотворение «Вечер» можно проверить по собранию стихов. Сопоставь предложенные строки с темами зимнего пути, тяжести мира и страха смерти.","Строки 1, 2 и 5 есть в «Вечере». «А когда настанет срок» и «Не смутят моих детей» в это стихотворение не входят."]},{"author":"А. Пиперски","question":"Как известно, хореическими называются стихи, написанные по схеме та́-та-та́-та-та́-та-… (например, <em>Буря мглою небо кроет</em>), а ямбическими — написанные по схеме та-та́-та-та́-та-та́-… (например, <em>Люблю грозу в начале мая</em>).\nВ хореических стихах чаще, чем в ямбических, встречаются ___________ придаточные, а в ямбических стихах чаще, чем в хореических, встречаются ___________ придаточные.","choices":["условные; временные и определительные","временные; условные и определительные","определительные; условные и временные","условные и определительные; временные","условные и временные; определительные."],"key":"А","review":["Размер и придаточные","В хорее сильное место приходится на первый слог пары, в ямбе — на второй. Проверь ударения в словах «если», «когда», «который».","«Е́сли» удобно начать хореическую строку, «когда́» и «кото́рый» — ямбическую. Поэтому условные придаточные чаще в хорее, временные и определительные — в ямбе."]},{"author":"А. Пиперски","question":"Даны русские слова и их польские соответствия, записанные в транскрипции ([w] — звук, средний между [у] и [в]): <em>молот</em> — [мwот], <em>горох</em> — [грох], <em>город —</em> [грут], <em>жёлоб —</em> [жwуп], <em>холод</em> — [хwут]. Как звучат польские соответствия слов <em>порог</em>, <em>мороз</em>, <em>голос</em>?","choices":["[прог], [мруз], [гwос]","[прук], [мрос], [гwус]","[прок], [мрус], [гwус]","[прок], [мрос], [гwос]","[прук], [мрус], [гwос]."],"key":"Д","review":["Польские соответствия","Сравни «порог» с «городом», а «голос» с «молотом». Обрати внимание, как меняются гласные внутри слова и звонкие согласные на конце.","«Порог» даёт [прук], как «город» даёт [грут]. «Мороз» даёт [мрус] с оглушением конечного [з], а «голос» — [гwос], как «молот» даёт [мwот]."]}], {"year":2016,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2016-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
